-- 294: Original BrillaPrep WASSCE BrillaPrep transitional Music beta content blueprint questions, part 2.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_294_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_294_guard;
INSERT INTO _migration_294_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_006' AND NOT (q.topic_id IS 'topic_was_music_b005_2' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which interval spans from C up to G?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. G major","B. A perfect fifth","C. A minor","D. Tone, tone, semitone"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Counting C as the first degree gives five letter names, and the major-scale distance is the perfect form of a fifth. Therefore the correct answer is B: A perfect fifth.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_006' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_294_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_007' AND NOT (q.topic_id IS 'topic_was_music_b005_2' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What key is indicated by one sharp in a major-key signature?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A minor","B. Tone, tone, semitone","C. G major","D. Every pitch moves up by the same interval while relationships are preserved"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The single sharp is F sharp, which supplies the leading note required by the G major scale. Therefore the correct answer is C: G major.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_007' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_294_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_008' AND NOT (q.topic_id IS 'topic_was_music_b005_2' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which minor key shares the key signature of C major?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Tone, tone, semitone","B. Every pitch moves up by the same interval while relationships are preserved","C. A perfect fifth","D. A minor"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A minor is the relative minor of C major and both use a key signature containing no sharps or flats. Therefore the correct answer is D: A minor.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_008' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_294_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_009' AND NOT (q.topic_id IS 'topic_was_music_b005_2' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What pattern begins a natural major scale from its tonic?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Tone, tone, semitone","B. Every pitch moves up by the same interval while relationships are preserved","C. A perfect fifth","D. G major"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The opening degrees of a major scale rise by two whole tones followed by a semitone between the third and fourth degrees. Therefore the correct answer is A: Tone, tone, semitone.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_009' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_294_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_music_b005_010' AND NOT (q.topic_id IS 'topic_was_music_b005_2' AND q.subject_id IS 'subj_wassce_music' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What changes when a melody is transposed up a major second?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A perfect fifth","B. Every pitch moves up by the same interval while relationships are preserved","C. G major","D. A minor"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Accurate transposition shifts all notes consistently so melodic contour and interval relationships remain recognisable in the new key. Therefore the correct answer is B: Every pitch moves up by the same interval while relationships are preserved.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_music_b005_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_music_b005_010' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Music practice aligned to official Ghana curriculum and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
